s = open('fuzz_expr.py').read()
start = s.index("class Gen:")
end = s.index("rng = random.Random(")
gen = '''class Gen:
    """Type-aware random expression generator."""

    def __init__(self, rng, decls, types, scope):
        self.rng = rng
        self.decls = decls
        self.types = types
        self.scope = scope
        self.ints = [n for n, t in scope.items() if isinstance(t, Int)]
        self.bools = [n for n, t in scope.items() if isinstance(t, Bool)]
        self.strings = [n for n, t in scope.items() if isinstance(t, String)]
        self.enums = [n for n, t in scope.items() if isinstance(t, type(types['E']))]
        self.arrays = [n for n, t in scope.items() if isinstance(t, type(types['V']))]
        self.chars = [n for n, t in scope.items() if isinstance(t, Char)]
        self.bits = {n: t.bits for n, t in scope.items() if isinstance(t, Int)}

    def const_of(self, name):
        rng = self.rng
        if name in self.bits:
            return ['const', name, rng.randint(0, (1 << self.bits[name]) - 1)]
        if name in self.bools:
            return ['const', name, rng.random() < 0.5]
        if name in self.strings:
            size = self.scope[name].maxsize
            return ['const', name, ''.join(rng.choice(['a', 'b', 'c', '\\x00', '\\xff'])
                                           for _ in range(size))]
        if name in self.enums:
            return ['const', name, rng.choice(['e0', 'e1', 'e2'])]
        if name in self.chars:
            return ['const', name, rng.choice(['\\x00', 'A', 'z', '\\xff'])]
        if name in self.arrays:
            return ['const', name, [rng.randint(0, 15)
                                    for _ in range(self.scope[name].size)]]
        if name in ('W', 'A', 'T', 'w', 'a'):
            return ['const', name, {'n': rng.randint(0, 15), 'b': rng.random() < 0.5,
                                    's': ''.join(rng.choice('ab\\x00') for _ in range(self.types['S'].maxsize)),
                                    'v': [rng.randint(0, 15) for _ in range(self.types['V'].size)]}]
        return ['const', name, 0]

    def scalar(self, depth, name):
        """An expression of the same underlying type as ``name``."""
        rng = self.rng
        if depth > 0 and rng.random() < 0.4:
            if name in self.bits and len(self.ints) > 0:
                op = rng.choice(['add', 'sub', 'eq', 'ne', 'lt', 'le', 'gt', 'ge'])
                if op in ('add', 'sub'):
                    return [op, self.scalar(depth - 1, name), self.scalar(depth - 1, name)]
                return [op, self.scalar(depth - 1, name), self.scalar(depth - 1, name)]
        if name in self.arrays and depth > 0 and self.scope[name].size > 0:
            return ['index', ['var', name], rng.randrange(self.scope[name].size)]
        if name in ('W', 'A', 'w', 'a') and depth > 0:
            return ['field', ['var', name], rng.choice(['n', 'b', 's', 'v'])]
        if name in ('T', 't') and depth > 0:
            return ['field', ['var', name], rng.choice(['n', 'b'])]
        if rng.random() < 0.6:
            return ['var', name]
        return self.const_of(name)

    def bool_expr(self, depth):
        rng = self.rng
        if depth <= 0:
            if self.bools and rng.random() < 0.7:
                return ['var', rng.choice(self.bools)]
            return ['eq', self.scalar(0, rng.choice(list(self.scope))),
                    self.scalar(0, rng.choice(list(self.scope)))]
        kind = rng.choice(['not', 'and', 'or', 'implies', 'eq', 'ne', 'lt', 'le',
                           'gt', 'ge', 'all', 'match', 'var', 'const'])
        if kind in ('not',):
            return ['not', self.bool_expr(depth - 1)]
        if kind in ('and', 'or', 'implies'):
            return [kind, self.bool_expr(depth - 1), self.bool_expr(depth - 1)]
        if kind in ('lt', 'le', 'gt', 'ge', 'add', 'sub'):
            name = rng.choice(self.ints or ['N'])
            return [kind, self.scalar(depth - 1, name), self.scalar(depth - 1, name)]
        if kind in ('eq', 'ne'):
            name = rng.choice(list(self.scope))
            return [kind, self.scalar(depth - 1, name), self.scalar(depth - 1, name)]
        if kind == 'all':
            name = rng.choice(self.arrays or ['V'])
            binding = 'z%d' % rng.randint(0, 3)
            inner_scope = dict(self.scope)
            inner_scope[binding] = self.types['N']
            sub = Gen(rng, self.decls, self.types, inner_scope)
            return ['all', binding, self.scalar(depth - 1, name), sub.bool_expr(depth - 1)]
        if kind == 'match':
            return ['match', self.scalar(depth - 1, rng.choice(self.strings or ['s'])),
                    self.pattern()]
        if kind == 'var':
            return ['var', rng.choice(self.bools or list(self.scope))]
        return self.const_of(rng.choice(self.bools or list(self.scope)))

    def pattern(self):
        rng = self.rng
        pieces = []
        for _ in range(rng.randint(0, 3)):
            alt = []
            for _ in range(rng.randint(0, 3)):
                atom = rng.choice(['a', 'b', 'c', '[a-c]', '[b-a]', '(a|b)', 'ab',
                                   '[ab]', '\\\\.', 'x', '[a-cx-z]', '()', 'a*b',
                                   '[\\\\]a]', '[a\\\\-b]'])
                if rng.random() < 0.35:
                    atom = atom + '*'
                alt.append(atom)
            pieces.append(''.join(alt))
        return '|'.join(pieces)

'''
open('fuzz_expr.py','w').write(s[:start] + gen + s[end:])
print('rewritten')
